/**
 * @typedef {object} JamilihOptions
 * @property {TraversalState} [$state]
 * @property {JamilihPlugin[]} [$plugins]
 * @property {MapWithRoot|[Map<HTMLElement,any>|WeakMap<HTMLElement,any>, any]} [$map]
 */

